import java.util.*;

class Solution {
  private static final long MOD = 1_000_000_007L;

  public int numberOfSequence(int n, int[] sick) {
    long[] fact = new long[n + 1], invFact = new long[n + 1];
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
    invFact[n] = power(fact[n], MOD - 2);
    for (int i = n; i > 0; i--) invFact[i - 1] = invFact[i] * i % MOD;
    long answer = fact[n - sick.length];
    int previous = -1;
    for (int i = 0; i < sick.length; i++) {
      int gap = sick[i] - previous - 1;
      answer = answer * invFact[gap] % MOD;
      if (previous != -1 && gap > 0) answer = answer * power(2, gap - 1) % MOD;
      previous = sick[i];
    }
    int gap = n - previous - 1;
    answer = answer * invFact[gap] % MOD;
    return (int) answer;
  }

  private long power(long a, long e) {
    long result = 1;
    while (e > 0) {
      if ((e & 1) != 0) result = result * a % MOD;
      a = a * a % MOD;
      e >>= 1;
    }
    return result;
  }
}
